import type { ShopMartSnapshot, ShopSnapshot, ShopPanelUiSnapshot, SubwayShopOfferSnapshot } from '../bus/snapshots.js';

function subwayShopOffersSignature(offers: SubwayShopOfferSnapshot[]): string {
  return offers.map((o) => `${o.id}|${o.canBuy}|${o.cost}|${o.isSoldOut}`).join(';');
}

function recyclerShardsSignature(shards: ShopSnapshot['recyclerShards']): string {
  return shards.map((s) => `${s.shardKey}|${s.count}|${s.dustValue}|${s.spriteUrl}`).join(';');
}

function recyclerDustOffersSignature(offers: ShopSnapshot['recyclerDustOffers']): string {
  return offers.map((o) => `${o.id}|${o.canBuy}|${o.costFormatted}|${o.levelLine}|${o.nextLevelLine}`).join(';');
}

/** Les cartes sont de petits objets plats : la sérialisation couvre tous leurs champs (état, remplissage, prix…). */
function cardsSignature(cards: ShopSnapshot['offers'] | ShopSnapshot['upgradeCards']): string {
  return JSON.stringify(cards);
}

export function shopCardsWouldChange(prev: ShopSnapshot['upgradeCards'], next: ShopSnapshot['upgradeCards']): boolean {
  return cardsSignature(prev) !== cardsSignature(next);
}

export function shopUiWouldChange(a: ShopPanelUiSnapshot, b: ShopPanelUiSnapshot): boolean {
  return !uiEqual(a, b);
}

function uiEqual(a: ShopPanelUiSnapshot, b: ShopPanelUiSnapshot): boolean {
  return (
    a.language === b.language
    && a.subTabsAriaLabel === b.subTabsAriaLabel
    && a.subGrocery === b.subGrocery
    && a.subUpgrades === b.subUpgrades
    && a.subTokens === b.subTokens
    && a.subTower === b.subTower
    && a.subSubway === b.subSubway
    && a.subRecycler === b.subRecycler
    && a.martTitle === b.martTitle
    && a.walletLabel === b.walletLabel
    && a.upgradesTitle === b.upgradesTitle
    && a.specialTitle === b.specialTitle
    && a.tokensUnit === b.tokensUnit
    && a.towerMarksUnit === b.towerMarksUnit
    && a.towerMarksTooltip === b.towerMarksTooltip
    && a.towerTitle === b.towerTitle
    && a.towerDesc === b.towerDesc
    && a.subwayTitle === b.subwayTitle
    && a.subwayDesc === b.subwayDesc
    && a.subwayBpLabel === b.subwayBpLabel
    && a.recyclerTotal === b.recyclerTotal
    && a.recyclerEssenceLabel === b.recyclerEssenceLabel
    && a.recyclerShardsTitle === b.recyclerShardsTitle
    && a.recyclerDustShopTitle === b.recyclerDustShopTitle
    && a.recyclerSearchPlaceholder === b.recyclerSearchPlaceholder
    && a.recyclerSortRarity === b.recyclerSortRarity
    && a.recyclerSortCount === b.recyclerSortCount
  );
}

export function shopMartWouldChange(prev: ShopMartSnapshot, next: ShopMartSnapshot): boolean {
  return (
    prev.martHtml !== next.martHtml
    || prev.martMoney !== next.martMoney
    || prev.martOfferTimer !== next.martOfferTimer
    || prev.martOfferTimerLabel !== next.martOfferTimerLabel
    || prev.martOfferProgress !== next.martOfferProgress
    || prev.martRestockLabel !== next.martRestockLabel
    || prev.autoPurchaseButtonLabel !== next.autoPurchaseButtonLabel
    || prev.autoPurchaseOn !== next.autoPurchaseOn
    || prev.autoPurchaseTooltip !== next.autoPurchaseTooltip
    || prev.martEmptyMessage !== next.martEmptyMessage
    || cardsSignature(prev.offers) !== cardsSignature(next.offers)
  );
}

export function shopMartTimerWouldChange(prev: ShopMartSnapshot, next: ShopMartSnapshot): boolean {
  return prev.martOfferTimer !== next.martOfferTimer
    || prev.martOfferTimerLabel !== next.martOfferTimerLabel
    || prev.martOfferProgress !== next.martOfferProgress
    || prev.martRestockLabel !== next.martRestockLabel;
}

export function pickShopMart(snap: ShopSnapshot): ShopMartSnapshot {
  return {
    martHtml: snap.martHtml,
    martMoney: snap.martMoney,
    martOfferTimer: snap.martOfferTimer,
    martOfferTimerLabel: snap.martOfferTimerLabel,
    martOfferProgress: snap.martOfferProgress,
    martRestockLabel: snap.martRestockLabel,
    autoPurchaseButtonLabel: snap.autoPurchaseButtonLabel,
    autoPurchaseOn: snap.autoPurchaseOn,
    autoPurchaseStateLabel: snap.autoPurchaseStateLabel,
    autoPurchaseTooltip: snap.autoPurchaseTooltip,
    offers: snap.offers,
    martEmptyMessage: snap.martEmptyMessage,
  };
}

export function shopSnapshotWouldChange(prev: ShopSnapshot, next: ShopSnapshot): boolean {
  return (
    !uiEqual(prev.ui, next.ui)
    || shopMartWouldChange(prev, next)
    || cardsSignature(prev.upgradeCards) !== cardsSignature(next.upgradeCards)
    || cardsSignature(prev.tokenCards) !== cardsSignature(next.tokenCards)
    || prev.questTokens !== next.questTokens
    || prev.towerShopHtml !== next.towerShopHtml
    || cardsSignature(prev.towerCards) !== cardsSignature(next.towerCards)
    || prev.triumphMarks !== next.triumphMarks
    || prev.subwayShopVisible !== next.subwayShopVisible
    || subwayShopOffersSignature(prev.subwayShopOffers) !== subwayShopOffersSignature(next.subwayShopOffers)
    || cardsSignature(prev.subwayCards) !== cardsSignature(next.subwayCards)
    || prev.subwayShopDesc !== next.subwayShopDesc
    || prev.subwayBP !== next.subwayBP
    || recyclerShardsSignature(prev.recyclerShards) !== recyclerShardsSignature(next.recyclerShards)
    || recyclerDustOffersSignature(prev.recyclerDustOffers) !== recyclerDustOffersSignature(next.recyclerDustOffers)
    || prev.recyclerShardsEmpty !== next.recyclerShardsEmpty
    || prev.essenceDust !== next.essenceDust
    || prev.recyclerSortRarityActive !== next.recyclerSortRarityActive
    || prev.recyclerSortCountActive !== next.recyclerSortCountActive
    || prev.recyclerSortMode !== next.recyclerSortMode
    || prev.recyclerSortDir !== next.recyclerSortDir
  );
}
